#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    int a[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
    }
    qsort(a, N, sizeof(int), cmp);

    // dp[s] = number of ways to achieve sum s using processed cards
    long long dp[K];
    for (int i = 0; i < K; i++) dp[i] = 0;
    dp[0] = 1;

    int unnecessary = 0;

    // First pass: count total ways for each sum
    for (int i = 0; i < N; i++) {
        for (int s = K - 1; s >= a[i]; s--) {
            dp[s] += dp[s - a[i]];
        }
    }

    // Now check each card
    for (int i = 0; i < N; i++) {
        // Temporarily remove this card's contribution
        long long ways_without[K];
        for (int s = 0; s < K; s++) ways_without[s] = dp[s];

        for (int s = a[i]; s < K; s++) {
            ways_without[s] -= ways_without[s - a[i]];
        }

        // Check if for every good set containing this card, removing it still good
        int is_unnecessary = 1;
        for (int s = K - a[i]; s < K; s++) {
            if (s < 0) continue;
            // Number of subsets with sum s that include this card
            long long ways_with = dp[s] - ways_without[s];
            if (ways_with > 0 && ways_without[s] == 0) {
                is_unnecessary = 0;
                break;
            }
        }
        if (is_unnecessary) unnecessary++;
    }

    printf("%d\n", unnecessary);
    return 0;
}

