static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    long long K;
    if (scanf("%d %lld", &N, &K) != 2) return 0;

    long long *a = (long long *)malloc(sizeof(long long) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    qsort(a, N, sizeof(long long), cmp_ll);

    /* dp[s] = whether some subset sum exactly s is possible, for s in [0, K-1].
       Sums >= K are not needed explicitly. */
    char *dp = (char *)calloc((size_t)K, sizeof(char));
    char *next = (char *)calloc((size_t)K, sizeof(char));
    dp[0] = 1;

    int unnecessary = 0;

    for (int i = 0; i < N; i++) {
        long long x = a[i];

        /* Check if card i is unnecessary.
           A card is necessary iff there exists a subset of other cards with sum s in [K-x, K-1].
           Then adding x makes the sum >= K, while without x it is < K. */
        long long L = K - x;
        if (L < 0) L = 0;

        int necessary = 0;
        for (long long s = L; s <= K - 1; s++) {
            if (dp[s]) {
                necessary = 1;
                break;
            }
        }
        if (!necessary) unnecessary++;

        /* Update dp by adding this card for subsequent checks. */
        memcpy(next, dp, (size_t)K);
        if (x < K) {
            for (long long s = 0; s + x < K; s++) {
                if (dp[s]) next[s + x] = 1;
            }
        }
        char *tmp = dp;
        dp = next;
        next = tmp;
    }

    printf("%d\n", unnecessary);

    free(a);
    free(dp);
    free(next);
    return 0;
}

