    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    sort(a.rbegin(), a.rend()); // sort descending

    long long total = 0;
    for (int x : a) total += x;

    // If total sum < K, no subset is good, but problem says positive ints and K given.
    // We still handle: all cards are unnecessary if no good subset exists.
    if (total < K) {
        cout << N << "\n";
        return 0;
    }

    vector<long long> suff(N + 1, 0);
    for (int i = N - 1; i >= 0; i--) {
        suff[i] = suff[i + 1] + a[i];
    }

    int unnecessary = 0;
    long long prefixSum = 0;
    for (int i = 0; i < N; i++) {
        // Without this card, can we still reach K?
        // Remaining sum after this card is suff[i+1] + prefixSum
        if (prefixSum + suff[i + 1] >= K) {
            unnecessary++;
        }
        prefixSum += a[i];
    }

    cout << unnecessary << "\n";
    return 0;
}

