int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    sort(a.begin(), a.end());

    // If a card itself is >= K, then any subset containing it is already good,
    // and removing it may make the subset not good. Such a card is necessary.
    // We will test each card i:
    // It is necessary iff there exists a subset sum s from other cards such that
    // K - a[i] <= s < K.
    //
    // If no such s exists, then whenever a subset containing a[i] is good,
    // removing a[i] still keeps sum >= K, so a[i] is unnecessary.

    int unnecessary = 0;

    for (int i = 0; i < N; i++) {
        vector<char> dp(K, 0); // dp[s] = whether sum s (< K) is achievable
        dp[0] = 1;

        for (int j = 0; j < N; j++) {
            if (j == i) continue;
            int x = a[j];
            for (int s = K - 1; s >= 0; s--) {
                if (!dp[s]) continue;
                int ns = s + x;
                if (ns < K) dp[ns] = 1;
            }
        }

        int L = max(0, K - a[i]);
        bool necessary = false;
        for (int s = L; s < K; s++) {
            if (dp[s]) {
                necessary = true;
                break;
            }
        }

        if (!necessary) unnecessary++;
    }

    cout << unnecessary << '\n';
    return 0;
}

