public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] a = new int[N];
        int totalSum = 0;
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
            totalSum += a[i];
        }

        // dp[s] = number of ways to achieve sum s using all cards (mod large to avoid overflow)
        // We'll use boolean-like approach with long to avoid overflow issues.
        long[] dp = new long[totalSum + 1];
        dp[0] = 1;
        for (int v : a) {
            for (int s = totalSum; s >= v; s--) {
                dp[s] += dp[s - v];
            }
        }

        int unnecessary = 0;
        for (int i = 0; i < N; i++) {
            int v = a[i];
            // Remove this card's contribution
            long[] dpWithout = dp.clone();
            for (int s = v; s <= totalSum; s++) {
                dpWithout[s] -= dpWithout[s - v];
            }
            // Now check if card i is unnecessary
            boolean isUnnecessary = true;
            for (int s = K; s <= totalSum; s++) {
                if (dpWithout[s - v] > 0) { // there is a subset without i that sums to s-v
                    // Then s is a good subset containing i
                    if (s - v < K) {
                        isUnnecessary = false;
                        break;
                    }
                }
            }
            if (isUnnecessary) unnecessary++;
        }

        System.out.println(unnecessary);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = sc.nextInt();

        // For each card i, check if subset of others can sum to [K-a[i], K-1]
        // Use forward/backward DP with boolean arrays up to K-1
        int maxSum = K; // we care about sums 0..K-1

        boolean[][] fwd = new boolean[N+1][maxSum];
        fwd[0][0] = true;
        for (int i = 0; i < N; i++) {
            for (int s = 0; s < maxSum; s++) {
                if (fwd[i][s]) {
                    fwd[i+1][s] = true;
                    if (s + a[i] < maxSum) fwd[i+1][s + a[i]] = true;
                }
            }
        }

        boolean[][] bwd = new boolean[N+2][maxSum];
        bwd[N][0] = true;
        for (int i = N-1; i >= 0; i--) {
            for (int s = 0; s < maxSum; s++) {
                if (bwd[i+1][s]) {
                    bwd[i][s] = true;
                    if (s + a[i] < maxSum) bwd[i][s + a[i]] = true;
                }
            }
        }

        int count = 0;
        for (int i = 0; i < N; i++) {
            if (a[i] >= K) continue; // not unnecessary
            int lo = K - a[i]; // need sum in [lo, K-1] from others
            boolean found = false;
            for (int s = lo; s < maxSum && !found; s++) {
                // check if s reachable without card i
                for (int t = 0; t <= s && !found; t++) {
                    if (fwd[i][t] && bwd[i+1][s-t]) found = true;
                }
            }
            if (!found) count++;
        }
        System.out.println(count);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int K = fs.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextInt();

        Arrays.sort(a);

        // A card x is unnecessary iff there is no subset of other cards
        // whose sum is in [K - x, K - 1].
        // This property is monotone after sorting:
        // if a card is unnecessary, then any smaller card is also unnecessary.
        int low = -1;   // unnecessary
        int high = N;   // not unnecessary

        while (high - low > 1) {
            int mid = (low + high) >>> 1;
            if (isUnnecessary(a, N, K, mid)) {
                low = mid;
            } else {
                high = mid;
            }
        }

        // indices [0..low] are unnecessary
        System.out.println(low + 1);
    }

    static boolean isUnnecessary(int[] a, int N, int K, int idx) {
        int x = a[idx];
        if (x >= K) return false; // alone it can make a good subset, so necessary

        // dp[s] = whether sum s (<K) can be made using all cards except idx
        boolean[] dp = new boolean[K];
        dp[0] = true;

        for (int i = 0; i < N; i++) {
            if (i == idx) continue;
            int v = a[i];
            for (int s = K - 1 - v; s >= 0; s--) {
                if (dp[s]) dp[s + v] = true;
            }
        }

        // If there exists sum s in [K-x, K-1], then adding x can be essential
        // to reach K, so x is necessary.
        int from = Math.max(0, K - x);
        for (int s = from; s < K; s++) {
            if (dp[s]) return false;
        }
        return true;
    }
}
